export type HotCard = {
  id: number; title: string; category: string; difficulty: '简单'|'中等'|'困难';
  question: string; idea: string; code: string; complexity: string; pitfall: string;
};

export const hot100: HotCard[] = [
  {id:1,title:'两数之和',category:'哈希',difficulty:'简单',question:'给定整数数组 nums 和目标值 target，返回和为 target 的两个整数下标。',idea:'我会边遍历边维护「数值 → 下标」的哈希表。对当前值 x，只需检查 target-x 是否已经出现；若出现立即返回，否则记录 x。这样每个元素只处理一次。',code:`class Solution:\n    def twoSum(self, nums, target):\n        seen = {}\n        for i, x in enumerate(nums):\n            if target - x in seen:\n                return [seen[target - x], i]\n            seen[x] = i`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'先查再存，避免 target=2x 时错误地重复使用同一元素。'},
  {id:49,title:'字母异位词分组',category:'哈希',difficulty:'中等',question:'将字符串数组中的字母异位词组合在一起。',idea:'异位词拥有相同的字符计数。我用 26 维计数元组作为哈希键，把字符串加入对应分组；相比排序键，长度为 k 的字符串只需 O(k)。',code:`from collections import defaultdict\n\n\nclass Solution:\n    def groupAnagrams(self, strs):\n        groups = defaultdict(list)\n        for word in strs:\n            count = [0] * 26\n            for ch in word:\n                count[ord(ch) - ord("a")] += 1\n            groups[tuple(count)].append(word)\n        return list(groups.values())`,complexity:'时间 O(Σk)，空间 O(Σk)。',pitfall:'列表不可哈希，必须转成 tuple；若字符集不限于小写字母可改用排序键。'},
  {id:128,title:'最长连续序列',category:'哈希',difficulty:'中等',question:'在未排序整数数组中，找出最长连续数字序列的长度，要求 O(n)。',idea:'先把所有数放入集合。只从没有前驱 x-1 的数开始向后枚举，这保证每段连续序列只被完整扫描一次，因此整体仍是线性时间。',code:`class Solution:\n    def longestConsecutive(self, nums):\n        values = set(nums)\n        best = 0\n        for x in values:\n            if x - 1 not in values:\n                y = x\n                while y in values:\n                    y += 1\n                best = max(best, y - x)\n        return best`,complexity:'平均时间 O(n)，空间 O(n)。',pitfall:'必须只从序列起点扩展；从每个数都扩展会退化到 O(n²)。'},
  {id:283,title:'移动零',category:'双指针',difficulty:'简单',question:'原地将数组中的所有 0 移到末尾，同时保持非零元素相对顺序。',idea:'用 slow 指向下一个非零元素应放的位置，fast 扫描数组；遇到非零就与 slow 交换并推进 slow。交换写法天然原地且保持顺序。',code:`class Solution:\n    def moveZeroes(self, nums):\n        slow = 0\n        for fast, x in enumerate(nums):\n            if x != 0:\n                nums[slow], nums[fast] = nums[fast], nums[slow]\n                slow += 1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'题目要求原地修改，不要创建新数组；slow 只在遇到非零时移动。'},
  {id:11,title:'盛最多水的容器',category:'双指针',difficulty:'中等',question:'从高度数组中选两条线，使它们与 x 轴组成的容器盛水最多。',idea:'左右指针从两端开始。面积由较短边决定，移动长边不可能改善当前短板，所以每次只移动较短边，并持续更新最大面积。',code:`class Solution:\n    def maxArea(self, height):\n        left, right, best = 0, len(height) - 1, 0\n        while left < right:\n            best = max(best, min(height[left], height[right]) * (right - left))\n            if height[left] < height[right]:\n                left += 1\n            else:\n                right -= 1\n        return best`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'面积是短边乘宽度；移动较高边无法弥补宽度减小。'},
  {id:15,title:'三数之和',category:'双指针',difficulty:'中等',question:'找出数组中所有和为 0 且不重复的三元组。',idea:'先排序，枚举第一个数，再在右侧用相向双指针寻找另外两个数。排序既提供单调性，也让去重变得直接。',code:`class Solution:\n    def threeSum(self, nums):\n        nums.sort()\n        ans = []\n        for i in range(len(nums) - 2):\n            if i and nums[i] == nums[i - 1]:\n                continue\n            if nums[i] > 0:\n                break\n            l, r = i + 1, len(nums) - 1\n            while l < r:\n                s = nums[i] + nums[l] + nums[r]\n                if s < 0:\n                    l += 1\n                elif s > 0:\n                    r -= 1\n                else:\n                    ans.append([nums[i], nums[l], nums[r]])\n                    l += 1\n                    r -= 1\n                    while l < r and nums[l] == nums[l - 1]:\n                        l += 1\n                    while l < r and nums[r] == nums[r + 1]:\n                        r -= 1\n        return ans`,complexity:'时间 O(n²)，除结果外空间 O(1)。',pitfall:'固定项与左右指针都要去重；排序后固定项大于 0 可直接结束。'},
  {id:42,title:'接雨水',category:'双指针',difficulty:'困难',question:'给定柱状图高度，计算下雨后能接多少水。',idea:'维护左右指针及两侧历史最高值。较低一侧的水位已经由该侧最高值确定，所以计算这一侧的积水并向内移动。',code:`class Solution:\n    def trap(self, height):\n        l, r = 0, len(height) - 1\n        left_max = right_max = water = 0\n        while l < r:\n            if height[l] <= height[r]:\n                left_max = max(left_max, height[l])\n                water += left_max - height[l]\n                l += 1\n            else:\n                right_max = max(right_max, height[r])\n                water += right_max - height[r]\n                r -= 1\n        return water`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'先更新最大值再累加，保证加数非负；移动的是当前较低的一侧。'},
  {id:3,title:'无重复字符的最长子串',category:'滑动窗口',difficulty:'中等',question:'求字符串中不含重复字符的最长连续子串长度。',idea:'窗口右端逐字符扩张，用字典记录字符最近下标。遇到窗口内重复字符时，左端直接跳到上次位置后一位，并且只能向右移动。',code:`class Solution:\n    def lengthOfLongestSubstring(self, s):\n        last = {}\n        left = best = 0\n        for right, ch in enumerate(s):\n            if ch in last:\n                left = max(left, last[ch] + 1)\n            last[ch] = right\n            best = max(best, right - left + 1)\n        return best`,complexity:'时间 O(n)，空间 O(字符集)。',pitfall:'左边界要取 max，不能被窗口外的旧重复位置拉回。'},
  {id:438,title:'找到字符串中所有字母异位词',category:'滑动窗口',difficulty:'中等',question:'返回 s 中所有与 p 互为字母异位词的子串起始下标。',idea:'先用 Counter 统计 p 和 s 的第一个定长窗口。之后窗口每次右移一格：加入右侧字符、移除左侧字符；两个 Counter 相等时，当前窗口就是一个字母异位词。',code:`from collections import Counter\n\n\nclass Solution:\n    def findAnagrams(self, s, p):\n        window_size = len(p)\n        if window_size > len(s):\n            return []\n\n        need = Counter(p)\n        window = Counter(s[:window_size])\n        answer = []\n\n        if window == need:\n            answer.append(0)\n\n        for right in range(window_size, len(s)):\n            left = right - window_size\n            left_char = s[left]\n            right_char = s[right]\n\n            window[right_char] += 1\n            window[left_char] -= 1\n            if window[left_char] == 0:\n                del window[left_char]\n\n            if window == need:\n                answer.append(left + 1)\n\n        return answer`,complexity:'时间 O(n)，空间 O(字符集)。题目限定小写字母，因此字符集大小最多为 26。',pitfall:'窗口长度始终保持为 len(p)；字符计数降为 0 时删除该键，让 Counter 保持简洁。'},
  {id:560,title:'和为 K 的子数组',category:'子串',difficulty:'中等',question:'统计连续子数组中元素和等于 k 的个数。',idea:'若当前前缀和为 prefix，需要之前出现过 prefix-k。用哈希表记录每个前缀和的出现次数，边遍历边累计答案。',code:`from collections import defaultdict\n\n\nclass Solution:\n    def subarraySum(self, nums, k):\n        count = defaultdict(int)\n        count[0] = 1\n        prefix = ans = 0\n        for x in nums:\n            prefix += x\n            ans += count[prefix - k]\n            count[prefix] += 1\n        return ans`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'初始化 count[0]=1 才能统计从下标 0 开始的子数组；必须存出现次数。'},
  {id:53,title:'最大子数组和',category:'普通数组',difficulty:'中等',question:'找出数组中和最大的连续子数组，返回其和。',idea:'Kadane 算法：以当前位置结尾的最优和，要么从当前元素重新开始，要么接在前一段之后。同步维护全局最大值。',code:`class Solution:\n    def maxSubArray(self, nums):\n        current = best = nums[0]\n        for x in nums[1:]:\n            current = max(x, current + x)\n            best = max(best, current)\n        return best`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'不能把初值设为 0，否则全负数组会返回错误答案。'},
  {id:56,title:'合并区间',category:'普通数组',difficulty:'中等',question:'合并所有重叠区间并返回互不重叠的区间。',idea:'先按左端点排序。当前区间若与答案末尾重叠，就扩展其右端点；否则开始一个新区间。',code:`class Solution:\n    def merge(self, intervals):\n        intervals.sort(key=lambda x: x[0])\n        ans = []\n        for start, end in intervals:\n            if not ans or start > ans[-1][1]:\n                ans.append([start, end])\n            else:\n                ans[-1][1] = max(ans[-1][1], end)\n        return ans`,complexity:'时间 O(n log n)，空间 O(n)（结果）。',pitfall:'端点相等也算重叠，所以新开区间的条件是 start > last_end。'},
  {id:189,title:'轮转数组',category:'普通数组',difficulty:'中等',question:'将数组向右轮转 k 个位置，要求原地完成。',idea:'把 k 对 n 取模。先整体反转，再反转前 k 个和后 n-k 个，三次反转恰好得到右移结果。',code:`class Solution:\n    def rotate(self, nums, k):\n        n = len(nums)\n        k %= n\n\n        def reverse(l, r):\n            while l < r:\n                nums[l], nums[r] = nums[r], nums[l]\n                l += 1\n                r -= 1\n\n        reverse(0, n - 1)\n        reverse(0, k - 1)\n        reverse(k, n - 1)`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'先做 k %= n；三次反转的区间端点不要写错。'},
  {id:238,title:'除自身以外数组的乘积',category:'普通数组',difficulty:'中等',question:'不使用除法，在 O(n) 时间内返回每个位置除自身外的乘积。',idea:'答案先存每个位置左侧乘积，再从右向左维护右侧乘积并乘入答案；这样无需额外的前后缀数组。',code:`class Solution:\n    def productExceptSelf(self, nums):\n        ans = [1] * len(nums)\n        prefix = 1\n        for i, x in enumerate(nums):\n            ans[i] = prefix\n            prefix *= x\n        suffix = 1\n        for i in range(len(nums) - 1, -1, -1):\n            ans[i] *= suffix\n            suffix *= nums[i]\n        return ans`,complexity:'时间 O(n)，除答案外空间 O(1)。',pitfall:'先写入前缀再乘当前值，后缀同理；该写法自然处理数组中的 0。'},
  {id:41,title:'缺失的第一个正数',category:'普通数组',difficulty:'困难',question:'在 O(n) 时间、O(1) 额外空间内找到未出现的最小正整数。',idea:'答案一定在 [1,n+1]。把值 x 原地交换到下标 x-1，直到每个可放置的数归位；最后第一个 nums[i] != i+1 的位置就是答案。',code:`class Solution:\n    def firstMissingPositive(self, nums):\n        n = len(nums)\n        for i in range(n):\n            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:\n                j = nums[i] - 1\n                nums[i], nums[j] = nums[j], nums[i]\n        for i, x in enumerate(nums):\n            if x != i + 1:\n                return i + 1\n        return n + 1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'while 中必须检查目标位置不是同值，避免重复元素导致死循环。'},
  {id:73,title:'矩阵置零',category:'矩阵',difficulty:'中等',question:'若矩阵某元素为 0，则将其所在行和列全部置零，要求原地。',idea:'用第一行和第一列充当标记数组，并单独记录第一列是否需要清零。先标记，再从后向前写零，避免标记过早被破坏。',code:`class Solution:\n    def setZeroes(self, matrix):\n        m, n = len(matrix), len(matrix[0])\n        first_col = any(matrix[i][0] == 0 for i in range(m))\n        for i in range(m):\n            for j in range(1, n):\n                if matrix[i][j] == 0:\n                    matrix[i][0] = matrix[0][j] = 0\n        for i in range(m - 1, -1, -1):\n            for j in range(n - 1, 0, -1):\n                if matrix[i][0] == 0 or matrix[0][j] == 0:\n                    matrix[i][j] = 0\n            if first_col:\n                matrix[i][0] = 0`,complexity:'时间 O(mn)，空间 O(1)。',pitfall:'第一列与 matrix[0][0] 共用位置，需额外布尔量；回填要从后向前。'},
  {id:54,title:'螺旋矩阵',category:'矩阵',difficulty:'中等',question:'按顺时针螺旋顺序返回矩阵中的所有元素。',idea:'维护 top、bottom、left、right 四条边界，每轮依次遍历上、右、下、左，遍历后收缩对应边界。',code:`class Solution:\n    def spiralOrder(self, matrix):\n        ans = []\n        top, bottom = 0, len(matrix) - 1\n        left, right = 0, len(matrix[0]) - 1\n        while top <= bottom and left <= right:\n            ans += matrix[top][left : right + 1]\n            top += 1\n            for i in range(top, bottom + 1):\n                ans.append(matrix[i][right])\n            right -= 1\n            if top <= bottom:\n                ans += matrix[bottom][left : right + 1][::-1]\n                bottom -= 1\n            if left <= right:\n                for i in range(bottom, top - 1, -1):\n                    ans.append(matrix[i][left])\n                left += 1\n        return ans`,complexity:'时间 O(mn)，除结果外空间 O(1)。',pitfall:'遍历下边和左边前要再次检查边界，避免单行或单列重复加入。'},
  {id:160,title:'相交链表',category:'链表',difficulty:'简单',question:'找到两个单链表相交的起始节点；不存在则返回空。',idea:'两个指针分别走 A→B 与 B→A。交换链表后两者都走过 m+n 距离，会在交点或共同的 None 相遇。',code:`class Solution:\n    def getIntersectionNode(self, headA, headB):\n        a, b = headA, headB\n        while a is not b:\n            a = headB if a is None else a.next\n            b = headA if b is None else b.next\n        return a`,complexity:'时间 O(m+n)，空间 O(1)。',pitfall:'判断的是节点身份 is，而不是节点值；没有交点时最终也会在 None 相遇。'},
  {id:206,title:'反转链表',category:'链表',difficulty:'简单',question:'反转单链表并返回新的头节点。',idea:'迭代维护 prev、cur、next_node。先保存下一节点，再反转当前指针，最后整体向前推进。',code:`class Solution:\n    def reverseList(self, head):\n        prev, cur = None, head\n        while cur:\n            next_node = cur.next\n            cur.next = prev\n            prev, cur = cur, next_node\n        return prev`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'改写 cur.next 之前必须保存原 next，否则会丢失剩余链表。'},
  {id:234,title:'回文链表',category:'链表',difficulty:'简单',question:'判断单链表是否为回文链表，要求 O(1) 额外空间。',idea:'快慢指针找到中点，反转后半段，再从两端逐节点比较。面试中可补充：若接口要求无副作用，比较后再恢复链表。',code:`class Solution:\n    def isPalindrome(self, head):\n        slow = fast = head\n        while fast and fast.next:\n            slow, fast = slow.next, fast.next.next\n        prev = None\n        while slow:\n            slow.next, prev, slow = prev, slow, slow.next\n        left, right = head, prev\n        while right:\n            if left.val != right.val:\n                return False\n            left, right = left.next, right.next\n        return True`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'只需比较后半段长度；Python 多重赋值右侧会先求值，因此可安全原地反转。'},
  {id:141,title:'环形链表',category:'链表',difficulty:'简单',question:'判断链表中是否存在环。',idea:'Floyd 快慢指针：slow 每次一步，fast 每次两步。若有环，快指针一定会在环内追上慢指针；无环则 fast 先到 None。',code:`class Solution:\n    def hasCycle(self, head):\n        slow = fast = head\n        while fast and fast.next:\n            slow = slow.next\n            fast = fast.next.next\n            if slow is fast:\n                return True\n        return False`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'循环条件必须同时检查 fast 和 fast.next。'},
  {id:142,title:'环形链表 II',category:'链表',difficulty:'中等',question:'若链表有环，返回入环的第一个节点。',idea:'快慢指针相遇后，把一个指针移回头部，之后两者都每次走一步，再次相遇处就是环入口。依据是头到入口距离等于相遇点继续绕到入口的距离模环长。',code:`class Solution:\n    def detectCycle(self, head):\n        slow = fast = head\n        while fast and fast.next:\n            slow, fast = slow.next, fast.next.next\n            if slow is fast:\n                slow = head\n                while slow is not fast:\n                    slow, fast = slow.next, fast.next\n                return slow\n        return None`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'第二阶段两个指针都走一步；比较节点身份而非值。'},
  {id:21,title:'合并两个有序链表',category:'链表',difficulty:'简单',question:'合并两个升序链表并返回新链表头节点。',idea:'使用哨兵节点和 tail 指针，每次接上较小节点，最后把未遍历完的链表整体接到尾部。',code:`class Solution:\n    def mergeTwoLists(self, list1, list2):\n        dummy = tail = ListNode()\n        while list1 and list2:\n            if list1.val <= list2.val:\n                tail.next, list1 = list1, list1.next\n            else:\n                tail.next, list2 = list2, list2.next\n            tail = tail.next\n        tail.next = list1 or list2\n        return dummy.next`,complexity:'时间 O(m+n)，空间 O(1)。',pitfall:'返回 dummy.next；循环后别忘了接上剩余链表。'},
  {id:2,title:'两数相加',category:'链表',difficulty:'中等',question:'两个链表逆序表示非负整数，返回它们的和对应的链表。',idea:'同步遍历两条链表并维护进位 carry。每轮把两节点值和进位相加，用 divmod 得到新进位和当前位；只要节点或进位仍存在就继续。',code:`class Solution:\n    def addTwoNumbers(self, l1, l2):\n        dummy = tail = ListNode()\n        carry = 0\n        while l1 or l2 or carry:\n            total = carry\n            if l1:\n                total += l1.val\n                l1 = l1.next\n            if l2:\n                total += l2.val\n                l2 = l2.next\n            carry, digit = divmod(total, 10)\n            tail.next = ListNode(digit)\n            tail = tail.next\n        return dummy.next`,complexity:'时间 O(max(m,n))，空间 O(max(m,n))（结果）。',pitfall:'循环条件必须包含 carry，处理最高位进位。'},
  {id:19,title:'删除链表的倒数第 N 个结点',category:'链表',difficulty:'中等',question:'删除链表倒数第 n 个节点，并返回头节点。',idea:'增加哨兵节点，让 fast 先走 n+1 步，再让 fast、slow 同步移动；fast 到空时 slow 正好停在待删节点前驱。',code:`class Solution:\n    def removeNthFromEnd(self, head, n):\n        dummy = ListNode(0, head)\n        fast = slow = dummy\n        for _ in range(n + 1):\n            fast = fast.next\n        while fast:\n            fast, slow = fast.next, slow.next\n        slow.next = slow.next.next\n        return dummy.next`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'哨兵统一删除头节点的情况；这里 fast 先走 n+1 步。'},
  {id:24,title:'两两交换链表中的节点',category:'链表',difficulty:'中等',question:'两两交换链表相邻节点，不能只交换节点值。',idea:'用 dummy 指向头部，prev 始终指向待交换二元组的前驱。保存 first、second 后调整三条连接，再把 prev 移到 first。',code:`class Solution:\n    def swapPairs(self, head):\n        dummy = ListNode(0, head)\n        prev = dummy\n        while prev.next and prev.next.next:\n            first, second = prev.next, prev.next.next\n            first.next = second.next\n            second.next = first\n            prev.next = second\n            prev = first\n        return dummy.next`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'交换后 prev 应移动到原 first；画出三条边再写代码。'},
  {id:25,title:'K 个一组翻转链表',category:'链表',difficulty:'困难',question:'每 k 个节点一组翻转链表，不足 k 个保持原顺序。',idea:'用 dummy 和 group_prev。先找到本组第 k 个节点，若不足直接返回；再以 group_next 为初始 prev 原地反转这一组，最后连接并推进到下一组。',code:`class Solution:\n    def reverseKGroup(self, head, k):\n        dummy = ListNode(0, head)\n        group_prev = dummy\n        while True:\n            kth = group_prev\n            for _ in range(k):\n                kth = kth.next\n                if not kth:\n                    return dummy.next\n            group_next = kth.next\n            prev, cur = group_next, group_prev.next\n            while cur is not group_next:\n                cur.next, prev, cur = prev, cur, cur.next\n            old_start = group_prev.next\n            group_prev.next = kth\n            group_prev = old_start`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'不足 k 个不能翻；反转前保存 group_next 和本组旧起点。'},
  {id:138,title:'随机链表的复制',category:'链表',difficulty:'中等',question:'深拷贝带 next 与 random 指针的链表。',idea:'最稳妥的面试写法是两遍哈希：第一遍为每个原节点创建副本，第二遍连接副本的 next 和 random。清晰度优先，若追问 O(1) 空间再讲穿插节点法。',code:`class Solution:\n    def copyRandomList(self, head):\n        if not head:\n            return None\n        copies = {None: None}\n        cur = head\n        while cur:\n            copies[cur] = Node(cur.val)\n            cur = cur.next\n        cur = head\n        while cur:\n            copies[cur].next = copies[cur.next]\n            copies[cur].random = copies[cur.random]\n            cur = cur.next\n        return copies[head]`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'给 None 预设映射可消除边界判断；不能让副本指针仍指向原节点。'},
  {id:148,title:'排序链表',category:'链表',difficulty:'中等',question:'在 O(n log n) 时间内对链表排序。',idea:'链表适合归并排序：快慢指针拆成两半，递归排序后线性合并。它不需要随机访问，合并可原地重连节点。',code:`class Solution:\n    def sortList(self, head):\n        if not head or not head.next:\n            return head\n        slow, fast = head, head.next\n        while fast and fast.next:\n            slow, fast = slow.next, fast.next.next\n        right = slow.next\n        slow.next = None\n        left = self.sortList(head)\n        right = self.sortList(right)\n        dummy = tail = ListNode()\n        while left and right:\n            if left.val <= right.val:\n                tail.next, left = left, left.next\n            else:\n                tail.next, right = right, right.next\n            tail = tail.next\n        tail.next = left or right\n        return dummy.next`,complexity:'时间 O(n log n)，递归栈 O(log n)。',pitfall:'用 fast=head.next 可让 slow 停在左半段末尾；拆分时要断开 slow.next。'},
  {id:23,title:'合并 K 个升序链表',category:'链表',difficulty:'困难',question:'合并 k 条升序链表并返回一条升序链表。',idea:'维护大小至多为 k 的最小堆，每条链表只放当前头节点。弹出最小节点接到结果，并把它的 next 入堆；计数器用于值相同时避免比较节点对象。',code:`import heapq, itertools\n\n\nclass Solution:\n    def mergeKLists(self, lists):\n        heap = []\n        counter = itertools.count()\n        for node in lists:\n            if node:\n                heapq.heappush(heap, (node.val, next(counter), node))\n        dummy = tail = ListNode()\n        while heap:\n            _, _, node = heapq.heappop(heap)\n            tail.next = node\n            tail = node\n            if node.next:\n                heapq.heappush(heap, (node.next.val, next(counter), node.next))\n        return dummy.next`,complexity:'N 个节点时 O(N log k)，空间 O(k)。',pitfall:'Python 元组前两项相同时会继续比较 Node，因此需要唯一计数器。'},
  {id:146,title:'LRU 缓存',category:'链表',difficulty:'中等',question:'设计 get/put 均为 O(1) 的最近最少使用缓存。',idea:'哈希表提供 O(1) 定位，双向链表维护最近使用顺序；头部最近、尾部最久。使用两个哨兵节点统一插入删除，访问后把节点移到头部。',code:`class Node:\n    def __init__(self, key=0, val=0):\n        self.key, self.val = key, val\n        self.prev = self.next = None\n\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.cap, self.cache = capacity, {}\n        self.head, self.tail = Node(), Node()\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def _remove(self, node):\n        node.prev.next, node.next.prev = node.next, node.prev\n\n    def _add(self, node):\n        node.next, node.prev = self.head.next, self.head\n        self.head.next.prev = node\n        self.head.next = node\n\n    def get(self, key):\n        if key not in self.cache:\n            return -1\n        node = self.cache[key]\n        self._remove(node)\n        self._add(node)\n        return node.val\n\n    def put(self, key, value):\n        if key in self.cache:\n            self._remove(self.cache[key])\n        node = Node(key, value)\n        self.cache[key] = node\n        self._add(node)\n        if len(self.cache) > self.cap:\n            lru = self.tail.prev\n            self._remove(lru)\n            del self.cache[lru.key]`,complexity:'get/put 均摊 O(1)，空间 O(capacity)。',pitfall:'更新已有 key 时先移除旧节点；淘汰时字典和链表都要删除。'},
  {id:94,title:'二叉树的中序遍历',category:'二叉树',difficulty:'简单',question:'返回二叉树节点值的中序遍历序列。',idea:'迭代写法使用栈：一路压入左链；到空后弹栈访问节点，再转向右子树。它直接对应递归的调用栈。',code:`class Solution:\n    def inorderTraversal(self, root):\n        ans, stack, cur = [], [], root\n        while cur or stack:\n            while cur:\n                stack.append(cur)\n                cur = cur.left\n            cur = stack.pop()\n            ans.append(cur.val)\n            cur = cur.right\n        return ans`,complexity:'时间 O(n)，空间 O(h)。',pitfall:'外层条件是 cur or stack；访问节点发生在左链走到底之后。'},
  {id:104,title:'二叉树的最大深度',category:'二叉树',difficulty:'简单',question:'返回二叉树的最大深度。',idea:'递归定义最清晰：空树深度为 0，非空树深度等于左右子树最大深度加 1。',code:`class Solution:\n    def maxDepth(self, root):\n        if not root:\n            return 0\n        return 1 + max(self.maxDepth(root.left), self.maxDepth(root.right))`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'深度按节点数计算，因此叶子节点深度为 1。'},
  {id:226,title:'翻转二叉树',category:'二叉树',difficulty:'简单',question:'翻转一棵二叉树的左右子树。',idea:'对每个节点交换左右孩子，再递归处理两棵子树。前序或后序都可以，关键是每个节点只交换一次。',code:`class Solution:\n    def invertTree(self, root):\n        if not root:\n            return None\n        root.left, root.right = self.invertTree(root.right), self.invertTree(root.left)\n        return root`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'右侧表达式先求值，Python 多重赋值可安全同时交换。'},
  {id:101,title:'对称二叉树',category:'二叉树',difficulty:'简单',question:'判断二叉树是否关于中心轴镜像对称。',idea:'定义 mirror(a,b)：两节点值相同，且 a.left 对应 b.right、a.right 对应 b.left。空节点必须成对出现。',code:`class Solution:\n    def isSymmetric(self, root):\n        def mirror(a, b):\n            if not a or not b:\n                return a is b\n            return (\n                a.val == b.val and mirror(a.left, b.right) and mirror(a.right, b.left)\n            )\n\n        return mirror(root.left, root.right) if root else True`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'比较的是交叉子树，而不是同方向子树。'},
  {id:543,title:'二叉树的直径',category:'二叉树',difficulty:'简单',question:'返回二叉树中任意两节点之间最长路径的边数。',idea:'后序遍历计算每个节点向下的最大深度。经过该节点的最长路径是左深度+右深度，用全局变量更新直径。',code:`class Solution:\n    def diameterOfBinaryTree(self, root):\n        self.best = 0\n\n        def depth(node):\n            if not node:\n                return 0\n            left, right = depth(node.left), depth(node.right)\n            self.best = max(self.best, left + right)\n            return 1 + max(left, right)\n\n        depth(root)\n        return self.best`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'depth 按节点数，left+right 恰好是边数，无需再减 1。'},
  {id:102,title:'二叉树的层序遍历',category:'二叉树',difficulty:'中等',question:'按层返回二叉树节点值。',idea:'使用队列做 BFS。每轮先记录当前队列长度，它就是本层节点数；只处理这批节点并把孩子加入队尾。',code:`from collections import deque\n\n\nclass Solution:\n    def levelOrder(self, root):\n        if not root:\n            return []\n        q, ans = deque([root]), []\n        while q:\n            level = []\n            for _ in range(len(q)):\n                node = q.popleft()\n                level.append(node.val)\n                if node.left:\n                    q.append(node.left)\n                if node.right:\n                    q.append(node.right)\n            ans.append(level)\n        return ans`,complexity:'时间 O(n)，空间 O(w)，w 为最大层宽。',pitfall:'进入 for 前固定 len(q)，否则会把下一层也处理进当前层。'},
  {id:108,title:'将有序数组转换为二叉搜索树',category:'二叉树',difficulty:'简单',question:'把升序数组转换为高度平衡的二叉搜索树。',idea:'每次选择区间中点作为根，左半区递归建左子树，右半区递归建右子树。中点划分保证高度差至多 1。',code:`class Solution:\n    def sortedArrayToBST(self, nums):\n        def build(left, right):\n            if left > right:\n                return None\n            mid = (left + right) // 2\n            root = TreeNode(nums[mid])\n            root.left = build(left, mid - 1)\n            root.right = build(mid + 1, right)\n            return root\n\n        return build(0, len(nums) - 1)`,complexity:'时间 O(n)，递归栈 O(log n)。',pitfall:'递归区间定义要统一；这里使用左右闭区间。'},
  {id:98,title:'验证二叉搜索树',category:'二叉树',difficulty:'中等',question:'判断一棵二叉树是否为合法二叉搜索树。',idea:'递归为每个节点传递合法开区间 (low,high)。当前值必须严格位于区间内，左子树收紧上界，右子树抬高下界。',code:`class Solution:\n    def isValidBST(self, root):\n        def valid(node, low, high):\n            if not node:\n                return True\n            if not low < node.val < high:\n                return False\n            return valid(node.left, low, node.val) and valid(node.right, node.val, high)\n\n        return valid(root, float("-inf"), float("inf"))`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'BST 是严格不等；只比较父子节点不够，必须传递祖先边界。'},
  {id:230,title:'二叉搜索树中第 K 小的元素',category:'二叉树',difficulty:'中等',question:'返回 BST 中第 k 小的节点值。',idea:'BST 的中序遍历是升序序列。迭代中序每弹出一个节点就把 k 减 1，减到 0 时立即返回。',code:`class Solution:\n    def kthSmallest(self, root, k):\n        stack, cur = [], root\n        while True:\n            while cur:\n                stack.append(cur)\n                cur = cur.left\n            cur = stack.pop()\n            k -= 1\n            if k == 0:\n                return cur.val\n            cur = cur.right`,complexity:'时间 O(h+k)，空间 O(h)。',pitfall:'计数发生在弹栈访问节点时，不是在压栈时。'},
  {id:199,title:'二叉树的右视图',category:'二叉树',difficulty:'中等',question:'返回从右侧能看到的每一层节点值。',idea:'优先 DFS 右子树，再 DFS 左子树。首次到达某个深度时看到的就是这一层最右节点，因此 depth 等于答案长度时记录。',code:`class Solution:\n    def rightSideView(self, root):\n        ans = []\n\n        def dfs(node, depth):\n            if not node:\n                return\n            if depth == len(ans):\n                ans.append(node.val)\n            dfs(node.right, depth + 1)\n            dfs(node.left, depth + 1)\n\n        dfs(root, 0)\n        return ans`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'必须先访问右子树；每层只在首次到达时记录。'},
  {id:114,title:'二叉树展开为链表',category:'二叉树',difficulty:'中等',question:'原地把二叉树按前序遍历顺序展开成只含 right 指针的链表。',idea:'倒序前序遍历（右→左→根），维护 prev。处理当前节点时令 right=prev、left=None，再更新 prev，天然得到前序链表。',code:`class Solution:\n    def flatten(self, root):\n        prev = None\n\n        def dfs(node):\n            nonlocal prev\n            if not node:\n                return\n            dfs(node.right)\n            dfs(node.left)\n            node.right = prev\n            node.left = None\n            prev = node\n\n        dfs(root)`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'必须先处理右再处理左；若先改 right 会丢失原子树。'},
  {id:105,title:'从前序与中序遍历序列构造二叉树',category:'二叉树',difficulty:'中等',question:'根据无重复值的前序和中序遍历构造二叉树。',idea:'前序首元素是根，在中序中的位置把区间分成左右子树。用哈希表 O(1) 查中序下标，并用前序游标按根→左→右消费节点。',code:`class Solution:\n    def buildTree(self, preorder, inorder):\n        pos = {x: i for i, x in enumerate(inorder)}\n        pre = 0\n\n        def build(left, right):\n            nonlocal pre\n            if left > right:\n                return None\n            value = preorder[pre]\n            pre += 1\n            root = TreeNode(value)\n            mid = pos[value]\n            root.left = build(left, mid - 1)\n            root.right = build(mid + 1, right)\n            return root\n\n        return build(0, len(inorder) - 1)`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'必须先递归左子树再递归右子树，才能匹配前序游标顺序。'},
  {id:437,title:'路径总和 III',category:'二叉树',difficulty:'中等',question:'统计二叉树中向下路径和等于 targetSum 的路径数量，路径可从任意节点开始。',idea:'DFS 维护从根到当前节点的前缀和。当前前缀为 s 时，之前出现的 s-target 都能形成一条合法路径；回溯离开节点时减去当前前缀计数。',code:`from collections import defaultdict\n\n\nclass Solution:\n    def pathSum(self, root, targetSum):\n        count = defaultdict(int)\n        count[0] = 1\n\n        def dfs(node, prefix):\n            if not node:\n                return 0\n            prefix += node.val\n            ans = count[prefix - targetSum]\n            count[prefix] += 1\n            ans += dfs(node.left, prefix) + dfs(node.right, prefix)\n            count[prefix] -= 1\n            return ans\n\n        return dfs(root, 0)`,complexity:'时间 O(n)，空间 O(h)。',pitfall:'离开节点必须回溯 count[prefix]，否则不同分支会相互污染。'},
  {id:236,title:'二叉树的最近公共祖先',category:'二叉树',difficulty:'中等',question:'返回二叉树中两个指定节点的最近公共祖先。',idea:'后序递归：遇到空、p 或 q 就向上返回。若左右子树都返回非空，当前节点就是最近公共祖先；否则把非空结果继续向上传递。',code:`class Solution:\n    def lowestCommonAncestor(self, root, p, q):\n        if not root or root is p or root is q:\n            return root\n        left = self.lowestCommonAncestor(root.left, p, q)\n        right = self.lowestCommonAncestor(root.right, p, q)\n        if left and right:\n            return root\n        return left or right`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'返回的是节点对象；当前节点等于 p/q 时要直接返回。'},
  {id:124,title:'二叉树中的最大路径和',category:'二叉树',difficulty:'困难',question:'求二叉树中任意非空路径的最大节点值之和，路径不能重复节点。',idea:'后序遍历。每个节点向父节点只能贡献一条单边路径，因此返回 val+max(left,right,0)；但经过当前节点的完整路径可同时取左右两边，用它更新全局答案。',code:`class Solution:\n    def maxPathSum(self, root):\n        self.best = float("-inf")\n\n        def gain(node):\n            if not node:\n                return 0\n            left = max(gain(node.left), 0)\n            right = max(gain(node.right), 0)\n            self.best = max(self.best, node.val + left + right)\n            return node.val + max(left, right)\n\n        gain(root)\n        return self.best`,complexity:'时间 O(n)，递归栈 O(h)。',pitfall:'全局答案初值必须是负无穷以处理全负树；向上只能选一侧。'},
  {id:200,title:'岛屿数量',category:'图论',difficulty:'中等',question:'统计由 1 组成且四方向连通的岛屿数量。',idea:'扫描网格，每发现一个未访问陆地就把答案加 1，并用 DFS/BFS 把整座岛标记为水。原地标记可省 visited 集合。',code:`class Solution:\n    def numIslands(self, grid):\n        m, n = len(grid), len(grid[0])\n\n        def dfs(i, j):\n            if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != "1":\n                return\n            grid[i][j] = "0"\n            dfs(i + 1, j)\n            dfs(i - 1, j)\n            dfs(i, j + 1)\n            dfs(i, j - 1)\n\n        ans = 0\n        for i in range(m):\n            for j in range(n):\n                if grid[i][j] == "1":\n                    ans += 1\n                    dfs(i, j)\n        return ans`,complexity:'时间 O(mn)，最坏递归栈 O(mn)。',pitfall:'输入元素通常是字符串 "1"/"0"；发现陆地后立即标记，避免重复访问。'},
  {id:994,title:'腐烂的橘子',category:'图论',difficulty:'中等',question:'每分钟腐烂橘子感染相邻新鲜橘子，求全部腐烂的最少分钟数。',idea:'这是多源 BFS：把所有初始腐烂橘子同时入队，统计新鲜数。逐层扩散，每处理一层代表一分钟；最终若仍有新鲜橘子则返回 -1。',code:`from collections import deque\n\n\nclass Solution:\n    def orangesRotting(self, grid):\n        m, n = len(grid), len(grid[0])\n        q = deque()\n        fresh = 0\n        for i in range(m):\n            for j in range(n):\n                if grid[i][j] == 2:\n                    q.append((i, j))\n                elif grid[i][j] == 1:\n                    fresh += 1\n        minutes = 0\n        while q and fresh:\n            for _ in range(len(q)):\n                i, j = q.popleft()\n                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                    x, y = i + di, j + dj\n                    if 0 <= x < m and 0 <= y < n and grid[x][y] == 1:\n                        grid[x][y] = 2\n                        fresh -= 1\n                        q.append((x, y))\n            minutes += 1\n        return minutes if fresh == 0 else -1`,complexity:'时间 O(mn)，空间 O(mn)。',pitfall:'没有新鲜橘子时答案为 0；用 while q and fresh 避免多算一分钟。'},
  {id:207,title:'课程表',category:'图论',difficulty:'中等',question:'判断是否能完成所有课程，即先修关系图是否有环。',idea:'拓扑排序：统计每门课入度，把入度 0 的课程入队。每取出一门课就删除其出边；若最终处理数量等于课程总数，图无环。',code:`from collections import deque\n\n\nclass Solution:\n    def canFinish(self, numCourses, prerequisites):\n        graph = [[] for _ in range(numCourses)]\n        indegree = [0] * numCourses\n        for course, pre in prerequisites:\n            graph[pre].append(course)\n            indegree[course] += 1\n        q = deque(i for i, d in enumerate(indegree) if d == 0)\n        taken = 0\n        while q:\n            pre = q.popleft()\n            taken += 1\n            for course in graph[pre]:\n                indegree[course] -= 1\n                if indegree[course] == 0:\n                    q.append(course)\n        return taken == numCourses`,complexity:'时间 O(V+E)，空间 O(V+E)。',pitfall:'边方向是 pre→course；最后比较处理课程数而非队列是否为空。'},
  {id:208,title:'实现 Trie（前缀树）',category:'图论',difficulty:'中等',question:'实现 Trie 的插入、完整单词搜索和前缀搜索。',idea:'每个节点存 children 字典与 end 标记。三个操作共享“沿字符向下走”的逻辑；完整搜索额外要求终点 end=True。',code:`class Trie:\n    def __init__(self):\n        self.children = {}\n        self.end = False\n\n    def insert(self, word):\n        node = self\n        for ch in word:\n            node = node.children.setdefault(ch, Trie())\n        node.end = True\n\n    def _find(self, text):\n        node = self\n        for ch in text:\n            if ch not in node.children:\n                return None\n            node = node.children[ch]\n        return node\n\n    def search(self, word):\n        node = self._find(word)\n        return bool(node and node.end)\n\n    def startsWith(self, prefix):\n        return self._find(prefix) is not None`,complexity:'每个操作时间 O(L)，插入总空间 O(字符总数)。',pitfall:'search 必须检查 end；startsWith 只需路径存在。'},
  {id:46,title:'全排列',category:'回溯',difficulty:'中等',question:'返回不含重复数字数组的所有排列。',idea:'回溯维护当前 path 与 used。每层选择一个未使用元素，递归后撤销选择；path 长度达到 n 时复制加入答案。',code:`class Solution:\n    def permute(self, nums):\n        ans = []\n        used = [False] * len(nums)\n\n        def backtrack(path):\n            if len(path) == len(nums):\n                ans.append(path[:])\n                return\n            for i, x in enumerate(nums):\n                if used[i]:\n                    continue\n                used[i] = True\n                path.append(x)\n                backtrack(path)\n                path.pop()\n                used[i] = False\n\n        backtrack([])\n        return ans`,complexity:'时间 O(n·n!)，空间 O(n)（不含结果）。',pitfall:'加入答案时要复制 path；递归回来必须同时撤销 path 和 used。'},
  {id:78,title:'子集',category:'回溯',difficulty:'中等',question:'返回无重复元素数组的所有子集。',idea:'每个递归节点本身就是一个合法子集，先加入答案，再从 start 之后依次选择下一个元素，避免产生不同顺序的重复集合。',code:`class Solution:\n    def subsets(self, nums):\n        ans = []\n\n        def backtrack(start, path):\n            ans.append(path[:])\n            for i in range(start, len(nums)):\n                path.append(nums[i])\n                backtrack(i + 1, path)\n                path.pop()\n\n        backtrack(0, [])\n        return ans`,complexity:'时间 O(n·2ⁿ)，递归空间 O(n)。',pitfall:'使用 start 而非 used；每个递归节点都要收集，不只叶子。'},
  {id:17,title:'电话号码的字母组合',category:'回溯',difficulty:'中等',question:'给定数字字符串 2-9，返回其所有可能字母组合。',idea:'每一层处理一个数字，枚举其映射字母并递归到下一位。到达 digits 末尾时收集当前字符串。',code:`class Solution:\n    def letterCombinations(self, digits):\n        if not digits:\n            return []\n        mp = {\n            "2": "abc",\n            "3": "def",\n            "4": "ghi",\n            "5": "jkl",\n            "6": "mno",\n            "7": "pqrs",\n            "8": "tuv",\n            "9": "wxyz",\n        }\n        ans = []\n\n        def dfs(i, path):\n            if i == len(digits):\n                ans.append("".join(path))\n                return\n            for ch in mp[digits[i]]:\n                path.append(ch)\n                dfs(i + 1, path)\n                path.pop()\n\n        dfs(0, [])\n        return ans`,complexity:'最多 O(4ⁿ·n)，递归空间 O(n)。',pitfall:'空输入返回空列表而不是包含空字符串的列表。'},
  {id:39,title:'组合总和',category:'回溯',difficulty:'中等',question:'候选数字可重复选择，返回和为 target 的所有不同组合。',idea:'排序后从 start 开始枚举，选中 candidates[i] 后仍从 i 递归，因此允许重复选；若当前数大于剩余值即可剪枝。',code:`class Solution:\n    def combinationSum(self, candidates, target):\n        candidates.sort()\n        ans = []\n\n        def dfs(start, remain, path):\n            if remain == 0:\n                ans.append(path[:])\n                return\n            for i in range(start, len(candidates)):\n                x = candidates[i]\n                if x > remain:\n                    break\n                path.append(x)\n                dfs(i, remain - x, path)\n                path.pop()\n\n        dfs(0, target, [])\n        return ans`,complexity:'指数级，递归深度最多 target/min(candidates)。',pitfall:'递归传 i 而不是 i+1 才允许重复选择；排序后才能 break 剪枝。'},
  {id:22,title:'括号生成',category:'回溯',difficulty:'中等',question:'生成 n 对括号的所有合法组合。',idea:'状态只需已用左括号数 open 与右括号数 close。open<n 时可放左括号；close<open 时才能放右括号，保证任意前缀合法。',code:`class Solution:\n    def generateParenthesis(self, n):\n        ans = []\n\n        def dfs(path, open_count, close_count):\n            if len(path) == 2 * n:\n                ans.append("".join(path))\n                return\n            if open_count < n:\n                path.append("(")\n                dfs(path, open_count + 1, close_count)\n                path.pop()\n            if close_count < open_count:\n                path.append(")")\n                dfs(path, open_count, close_count + 1)\n                path.pop()\n\n        dfs([], 0, 0)\n        return ans`,complexity:'答案数量为第 n 个卡特兰数，空间 O(n)。',pitfall:'右括号条件是 close<open；无需生成后再验证。'},
  {id:79,title:'单词搜索',category:'回溯',difficulty:'中等',question:'判断字符网格中是否存在由相邻单元格组成的给定单词。',idea:'从每个可能起点 DFS 匹配下一个字符。进入格子后临时标记为已访问，四向递归，返回前恢复；匹配完最后一个字符即成功。',code:`class Solution:\n    def exist(self, board, word):\n        m, n = len(board), len(board[0])\n\n        def dfs(i, j, k):\n            if k == len(word):\n                return True\n            if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != word[k]:\n                return False\n            ch = board[i][j]\n            board[i][j] = "#"\n            found = (\n                dfs(i + 1, j, k + 1)\n                or dfs(i - 1, j, k + 1)\n                or dfs(i, j + 1, k + 1)\n                or dfs(i, j - 1, k + 1)\n            )\n            board[i][j] = ch\n            return found\n\n        return any(dfs(i, j, 0) for i in range(m) for j in range(n))`,complexity:'最坏 O(mn·3ᴸ)，递归空间 O(L)。',pitfall:'无论成功失败都应恢复格子；进入后下一步最多三个新方向。'},
  {id:131,title:'分割回文串',category:'回溯',difficulty:'中等',question:'把字符串分割成若干回文子串，返回所有方案。',idea:'从 start 枚举当前片段终点；片段是回文时加入 path 并递归处理剩余后缀。到字符串末尾收集方案。',code:`class Solution:\n    def partition(self, s):\n        ans = []\n\n        def dfs(start, path):\n            if start == len(s):\n                ans.append(path[:])\n                return\n            for end in range(start + 1, len(s) + 1):\n                part = s[start:end]\n                if part == part[::-1]:\n                    path.append(part)\n                    dfs(end, path)\n                    path.pop()\n\n        dfs(0, [])\n        return ans`,complexity:'最坏 O(n·2ⁿ)，递归空间 O(n)。',pitfall:'切片右端点是开区间；收集 path 时复制。'},
  {id:51,title:'N 皇后',category:'回溯',difficulty:'困难',question:'返回 n 皇后问题的所有不同棋盘方案。',idea:'逐行放置皇后，用三组集合记录已占列、主对角线 r-c、次对角线 r+c。合法则选择，递归下一行，再撤销。',code:`class Solution:\n    def solveNQueens(self, n):\n        ans = []\n        cols = set()\n        diag1 = set()\n        diag2 = set()\n        board = [["."] * n for _ in range(n)]\n\n        def dfs(r):\n            if r == n:\n                ans.append(["".join(row) for row in board])\n                return\n            for c in range(n):\n                if c in cols or r - c in diag1 or r + c in diag2:\n                    continue\n                cols.add(c)\n                diag1.add(r - c)\n                diag2.add(r + c)\n                board[r][c] = "Q"\n                dfs(r + 1)\n                board[r][c] = "."\n                cols.remove(c)\n                diag1.remove(r - c)\n                diag2.remove(r + c)\n\n        dfs(0)\n        return ans`,complexity:'约 O(n!)，额外空间 O(n²) 棋盘与 O(n) 标记。',pitfall:'两条对角线分别用 r-c 和 r+c 唯一标识；回溯要完整撤销。'},
  {id:35,title:'搜索插入位置',category:'二分查找',difficulty:'简单',question:'在升序数组中返回目标下标；不存在则返回应插入位置。',idea:'寻找第一个大于等于 target 的位置，也就是 lower_bound。使用左闭右开区间 [left,right)，循环结束时 left 即答案。',code:`class Solution:\n    def searchInsert(self, nums, target):\n        left, right = 0, len(nums)\n        while left < right:\n            mid = (left + right) // 2\n            if nums[mid] < target:\n                left = mid + 1\n            else:\n                right = mid\n        return left`,complexity:'时间 O(log n)，空间 O(1)。',pitfall:'明确区间是左闭右开，right 初值为 len(nums)。'},
  {id:74,title:'搜索二维矩阵',category:'二分查找',difficulty:'中等',question:'每行升序且下一行首元素大于上一行尾元素，判断 target 是否存在。',idea:'把 m×n 矩阵视为长度 m·n 的一维升序数组，二分中用 divmod(mid,n) 映射回行列。',code:`class Solution:\n    def searchMatrix(self, matrix, target):\n        m, n = len(matrix), len(matrix[0])\n        left, right = 0, m * n - 1\n        while left <= right:\n            mid = (left + right) // 2\n            i, j = divmod(mid, n)\n            if matrix[i][j] == target:\n                return True\n            if matrix[i][j] < target:\n                left = mid + 1\n            else:\n                right = mid - 1\n        return False`,complexity:'时间 O(log(mn))，空间 O(1)。',pitfall:'一维下标映射是 row=mid//n、col=mid%n。'},
  {id:34,title:'在排序数组中查找元素的第一个和最后一个位置',category:'二分查找',difficulty:'中等',question:'返回 target 在有序数组中的起止下标，不存在则返回 [-1,-1]。',idea:'写一个 lower_bound(x) 找第一个 >=x 的位置。左边界是 lower_bound(target)，右边界是 lower_bound(target+1)-1；最后验证左边界确实是 target。',code:`class Solution:\n    def searchRange(self, nums, target):\n        def lower_bound(x):\n            left, right = 0, len(nums)\n            while left < right:\n                mid = (left + right) // 2\n                if nums[mid] < x:\n                    left = mid + 1\n                else:\n                    right = mid\n            return left\n\n        left = lower_bound(target)\n        if left == len(nums) or nums[left] != target:\n            return [-1, -1]\n        return [left, lower_bound(target + 1) - 1]`,complexity:'时间 O(log n)，空间 O(1)。',pitfall:'先验证 left 未越界且命中 target；该 target+1 写法依赖整数输入。'},
  {id:33,title:'搜索旋转排序数组',category:'二分查找',difficulty:'中等',question:'在无重复元素的旋转升序数组中查找 target 下标。',idea:'每次二分至少有一半有序。先判断左半还是右半有序，再判断 target 是否落在该有序区间，决定保留哪一半。',code:`class Solution:\n    def search(self, nums, target):\n        left, right = 0, len(nums) - 1\n        while left <= right:\n            mid = (left + right) // 2\n            if nums[mid] == target:\n                return mid\n            if nums[left] <= nums[mid]:\n                if nums[left] <= target < nums[mid]:\n                    right = mid - 1\n                else:\n                    left = mid + 1\n            else:\n                if nums[mid] < target <= nums[right]:\n                    left = mid + 1\n                else:\n                    right = mid - 1\n        return -1`,complexity:'时间 O(log n)，空间 O(1)。',pitfall:'左侧有序判断用 <=；区间端点的一边包含等号、另一边不包含。'},
  {id:153,title:'寻找旋转排序数组中的最小值',category:'二分查找',difficulty:'中等',question:'在无重复元素的旋转升序数组中找最小值。',idea:'把 nums[mid] 与 nums[right] 比较。mid 更大说明最小值在右侧且不含 mid；否则最小值在左侧且可能就是 mid。',code:`class Solution:\n    def findMin(self, nums):\n        left, right = 0, len(nums) - 1\n        while left < right:\n            mid = (left + right) // 2\n            if nums[mid] > nums[right]:\n                left = mid + 1\n            else:\n                right = mid\n        return nums[left]`,complexity:'时间 O(log n)，空间 O(1)。',pitfall:'与 right 比较更容易判断；else 中 right=mid 不能减 1。'},
  {id:4,title:'寻找两个正序数组的中位数',category:'二分查找',difficulty:'困难',question:'在 O(log(m+n)) 时间内求两个有序数组的中位数。',idea:'在较短数组上二分切分位置 i，另一个数组切分 j 由总左半长度决定。找到 maxLeftA≤minRightB 且 maxLeftB≤minRightA 的合法切分，再由奇偶性计算中位数。',code:`class Solution:\n    def findMedianSortedArrays(self, a, b):\n        if len(a) > len(b):\n            return self.findMedianSortedArrays(b, a)\n        m, n = len(a), len(b)\n        half = (m + n + 1) // 2\n        l, r = 0, m\n        while l <= r:\n            i = (l + r) // 2\n            j = half - i\n            al = a[i - 1] if i else float("-inf")\n            ar = a[i] if i < m else float("inf")\n            bl = b[j - 1] if j else float("-inf")\n            br = b[j] if j < n else float("inf")\n            if al > br:\n                r = i - 1\n            elif bl > ar:\n                l = i + 1\n            else:\n                if (m + n) % 2:\n                    return max(al, bl)\n                return (max(al, bl) + min(ar, br)) / 2`,complexity:'时间 O(log min(m,n))，空间 O(1)。',pitfall:'必须在短数组上二分；边界用 ±inf 统一处理空半区。'},
  {id:20,title:'有效的括号',category:'栈',difficulty:'简单',question:'判断只含括号的字符串是否有效配对。',idea:'遇到右括号时，它必须与栈顶左括号匹配。可以把“期望的右括号”压栈，遇到右括号直接与栈顶比较，最后栈必须为空。',code:`class Solution:\n    def isValid(self, s):\n        pairs = {"(": ")", "[": "]", "{": "}"}\n        stack = []\n        for ch in s:\n            if ch in pairs:\n                stack.append(pairs[ch])\n            elif not stack or stack.pop() != ch:\n                return False\n        return not stack`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'右括号到来时先检查栈非空；遍历结束还要确认栈为空。'},
  {id:155,title:'最小栈',category:'栈',difficulty:'中等',question:'设计支持 push、pop、top 和常数时间 getMin 的栈。',idea:'每次入栈同时保存“当前值、入栈后的最小值”。这样弹栈时历史最小值会自动恢复，无需额外扫描。',code:`class MinStack:\n    def __init__(self):\n        self.stack = []\n\n    def push(self, val):\n        current_min = val if not self.stack else min(val, self.stack[-1][1])\n        self.stack.append((val, current_min))\n\n    def pop(self):\n        self.stack.pop()\n\n    def top(self):\n        return self.stack[-1][0]\n\n    def getMin(self):\n        return self.stack[-1][1]`,complexity:'所有操作 O(1)，空间 O(n)。',pitfall:'相等的最小值也要随每个元素保存，避免弹出一个后丢失最小值。'},
  {id:394,title:'字符串解码',category:'栈',difficulty:'中等',question:'解码形如 k[encoded_string] 的嵌套字符串。',idea:'扫描字符，数字累积倍数；遇到 [ 时把外层字符串和倍数压栈并重置；遇到 ] 时弹栈，把当前段重复后拼回外层。',code:`class Solution:\n    def decodeString(self, s):\n        stack = []\n        current = ""\n        number = 0\n        for ch in s:\n            if ch.isdigit():\n                number = number * 10 + int(ch)\n            elif ch == "[":\n                stack.append((current, number))\n                current = ""\n                number = 0\n            elif ch == "]":\n                previous, times = stack.pop()\n                current = previous + current * times\n            else:\n                current += ch\n        return current`,complexity:'时间与输出长度成正比，栈空间 O(嵌套深度)。',pitfall:'倍数可能是多位数，必须 number=number*10+digit。'},
  {id:739,title:'每日温度',category:'栈',difficulty:'中等',question:'返回每一天要等几天才会出现更高温度。',idea:'维护温度单调不增的下标栈。当前温度更高时，不断弹出更低温度下标，并用当前下标差填写答案。',code:`class Solution:\n    def dailyTemperatures(self, temperatures):\n        ans = [0] * len(temperatures)\n        stack = []\n        for i, t in enumerate(temperatures):\n            while stack and temperatures[stack[-1]] < t:\n                j = stack.pop()\n                ans[j] = i - j\n            stack.append(i)\n        return ans`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'栈里存下标而不是温度；相等温度不能弹出。'},
  {id:84,title:'柱状图中最大的矩形',category:'栈',difficulty:'困难',question:'求柱状图中可勾勒出的最大矩形面积。',idea:'维护高度单调递增的下标栈。遇到更低柱时，弹出的柱高确定，右边界是当前下标，左边界是新栈顶；末尾加高度 0 的哨兵完成清算。',code:`class Solution:\n    def largestRectangleArea(self, heights):\n        stack = []\n        best = 0\n        for i, h in enumerate(heights + [0]):\n            while stack and heights[stack[-1]] > h:\n                height = heights[stack.pop()]\n                left = stack[-1] if stack else -1\n                best = max(best, height * (i - left - 1))\n            stack.append(i)\n        return best`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'宽度是 i-left-1；遍历 heights+[0] 时不会访问哨兵下标的高度。'},
  {id:215,title:'数组中的第 K 个最大元素',category:'堆',difficulty:'中等',question:'不完整排序，返回数组中第 k 大元素。',idea:'面试优先写 Quickselect：目标下标是 n-k。每次原地分区，把枢轴放到最终位置，再只进入包含目标的一侧。',code:`class Solution:\n    def findKthLargest(self, nums, k):\n        target = len(nums) - k\n        left, right = 0, len(nums) - 1\n        while True:\n            pivot = nums[right]\n            store = left\n            for i in range(left, right):\n                if nums[i] <= pivot:\n                    nums[store], nums[i] = nums[i], nums[store]\n                    store += 1\n            nums[store], nums[right] = nums[right], nums[store]\n            if store == target:\n                return nums[store]\n            if store < target:\n                left = store + 1\n            else:\n                right = store - 1`,complexity:'平均时间 O(n)，最坏 O(n²)，空间 O(1)。',pitfall:'第 k 大对应升序下标 n-k；随机枢轴可降低最坏情况概率。'},
  {id:347,title:'前 K 个高频元素',category:'堆',difficulty:'中等',question:'返回数组中出现频率最高的 k 个元素。',idea:'频率最多为 n，可用桶排序：先计数，再把数字放入“频率→数字列表”的桶，从高频向低频收集到 k 个。',code:`from collections import Counter\n\n\nclass Solution:\n    def topKFrequent(self, nums, k):\n        count = Counter(nums)\n        buckets = [[] for _ in range(len(nums) + 1)]\n        for x, freq in count.items():\n            buckets[freq].append(x)\n        ans = []\n        for freq in range(len(buckets) - 1, 0, -1):\n            for x in buckets[freq]:\n                ans.append(x)\n                if len(ans) == k:\n                    return ans`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'桶下标是频率，范围到 n；达到 k 后立即返回。'},
  {id:295,title:'数据流的中位数',category:'堆',difficulty:'困难',question:'设计结构支持不断添加数字并返回当前中位数。',idea:'用两个堆维护两半数据：small 是负数实现的大顶堆，large 是小顶堆。保证 small 长度等于 large 或多 1，且 small 的最大值不大于 large 的最小值。',code:`import heapq\n\n\nclass MedianFinder:\n    def __init__(self):\n        self.small = []\n        self.large = []\n\n    def addNum(self, num):\n        heapq.heappush(self.small, -num)\n        heapq.heappush(self.large, -heapq.heappop(self.small))\n        if len(self.large) > len(self.small):\n            heapq.heappush(self.small, -heapq.heappop(self.large))\n\n    def findMedian(self):\n        if len(self.small) > len(self.large):\n            return -self.small[0]\n        return (-self.small[0] + self.large[0]) / 2`,complexity:'add O(log n)，findMedian O(1)，空间 O(n)。',pitfall:'Python 只有小顶堆，small 存负数；每次插入后恢复大小平衡。'},
  {id:121,title:'买卖股票的最佳时机',category:'贪心',difficulty:'简单',question:'只允许买卖一次，求最大利润。',idea:'从左到右维护见过的最低价格。当天卖出的最好利润是 price-min_price，用它更新全局答案。',code:`class Solution:\n    def maxProfit(self, prices):\n        min_price = float("inf")\n        best = 0\n        for price in prices:\n            min_price = min(min_price, price)\n            best = max(best, price - min_price)\n        return best`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'必须先买后卖，所以最低价只来自当前天及之前。'},
  {id:55,title:'跳跃游戏',category:'贪心',difficulty:'中等',question:'判断能否从数组首位跳到最后一个下标。',idea:'维护当前能到达的最远下标 farthest。遍历到 i 时若 i 已超过 farthest，说明断档；否则用 i+nums[i] 扩展最远范围。',code:`class Solution:\n    def canJump(self, nums):\n        farthest = 0\n        for i, jump in enumerate(nums):\n            if i > farthest:\n                return False\n            farthest = max(farthest, i + jump)\n            if farthest >= len(nums) - 1:\n                return True\n        return True`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'先判断当前位置是否可达，再用它更新最远位置。'},
  {id:45,title:'跳跃游戏 II',category:'贪心',difficulty:'中等',question:'保证可达，求到最后一个下标的最少跳跃次数。',idea:'把每次跳跃看作 BFS 一层。扫描当前层范围，维护下一层最远位置；到达当前层边界时跳数加一，并把边界更新为 farthest。',code:`class Solution:\n    def jump(self, nums):\n        jumps = end = farthest = 0\n        for i in range(len(nums) - 1):\n            farthest = max(farthest, i + nums[i])\n            if i == end:\n                jumps += 1\n                end = farthest\n        return jumps`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'只遍历到 n-2，避免到终点后多算一次跳跃。'},
  {id:763,title:'划分字母区间',category:'贪心',difficulty:'中等',question:'把字符串划分为尽可能多的片段，使每个字母最多出现在一个片段。',idea:'先记录每个字符最后出现位置。扫描时维护当前片段必须覆盖的最远位置 end；当 i==end，当前片段已包含其中所有字符的最后一次出现，可以切分。',code:`class Solution:\n    def partitionLabels(self, s):\n        last = {ch: i for i, ch in enumerate(s)}\n        ans = []\n        start = end = 0\n        for i, ch in enumerate(s):\n            end = max(end, last[ch])\n            if i == end:\n                ans.append(end - start + 1)\n                start = i + 1\n        return ans`,complexity:'时间 O(n)，空间 O(字符集)。',pitfall:'end 是片段内所有字符最后位置的最大值，不只是当前字符的位置。'},
  {id:70,title:'爬楼梯',category:'动态规划',difficulty:'简单',question:'每次爬 1 或 2 阶，求到第 n 阶的不同方法数。',idea:'最后一步来自 n-1 或 n-2，因此 f(n)=f(n-1)+f(n-2)。只需两个变量滚动保存前两项。',code:`class Solution:\n    def climbStairs(self, n):\n        prev2, prev1 = 1, 1\n        for _ in range(2, n + 1):\n            prev2, prev1 = prev1, prev1 + prev2\n        return prev1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'把 f(0)=1、f(1)=1 作为统一初值。'},
  {id:118,title:'杨辉三角',category:'动态规划',difficulty:'简单',question:'返回杨辉三角的前 numRows 行。',idea:'每行首尾为 1，中间元素等于上一行相邻两项之和。按行构造即可。',code:`class Solution:\n    def generate(self, numRows):\n        triangle = []\n        for i in range(numRows):\n            row = [1] * (i + 1)\n            for j in range(1, i):\n                row[j] = triangle[i - 1][j - 1] + triangle[i - 1][j]\n            triangle.append(row)\n        return triangle`,complexity:'时间 O(n²)，结果空间 O(n²)。',pitfall:'中间位置范围是 1 到 i-1；首尾保持 1。'},
  {id:198,title:'打家劫舍',category:'动态规划',difficulty:'中等',question:'不能偷相邻房屋，求可偷到的最大金额。',idea:'遍历每间房，状态只有偷当前（前前状态+x）或不偷当前（前一状态）。用两个变量滚动更新。',code:`class Solution:\n    def rob(self, nums):\n        prev2 = prev1 = 0\n        for x in nums:\n            prev2, prev1 = prev1, max(prev1, prev2 + x)\n        return prev1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'多重赋值右侧用的是更新前的两个状态。'},
  {id:279,title:'完全平方数',category:'动态规划',difficulty:'中等',question:'求和为 n 的完全平方数的最少数量。',idea:'完全背包：dp[x] 表示组成 x 的最少个数。对每个 x 枚举不超过它的平方数 square，转移 dp[x]=min(dp[x],dp[x-square]+1)。',code:`class Solution:\n    def numSquares(self, n):\n        dp = [0] + [float("inf")] * n\n        for x in range(1, n + 1):\n            j = 1\n            while j * j <= x:\n                dp[x] = min(dp[x], dp[x - j * j] + 1)\n                j += 1\n        return dp[n]`,complexity:'时间 O(n√n)，空间 O(n)。',pitfall:'dp[0]=0 是所有转移的起点。'},
  {id:322,title:'零钱兑换',category:'动态规划',difficulty:'中等',question:'给定硬币面额和金额，求凑成金额所需的最少硬币数。',idea:'dp[x] 表示金额 x 的最少硬币数。对每个金额枚举硬币，从已求出的 dp[x-coin] 转移；不可达状态保持无穷。',code:`class Solution:\n    def coinChange(self, coins, amount):\n        dp = [0] + [float("inf")] * amount\n        for x in range(1, amount + 1):\n            for coin in coins:\n                if coin <= x:\n                    dp[x] = min(dp[x], dp[x - coin] + 1)\n        return -1 if dp[amount] == float("inf") else dp[amount]`,complexity:'时间 O(amount·len(coins))，空间 O(amount)。',pitfall:'这是求最少数量而非组合数；不可达时返回 -1。'},
  {id:139,title:'单词拆分',category:'动态规划',difficulty:'中等',question:'判断字符串能否由字典中的一个或多个单词拼接而成。',idea:'dp[i] 表示前 i 个字符能否拆分。若存在 j<i，使 dp[j] 为真且 s[j:i] 在字典中，则 dp[i] 为真。',code:`class Solution:\n    def wordBreak(self, s, wordDict):\n        words = set(wordDict)\n        dp = [False] * (len(s) + 1)\n        dp[0] = True\n        max_len = max(map(len, words), default=0)\n        for i in range(1, len(s) + 1):\n            for j in range(max(0, i - max_len), i):\n                if dp[j] and s[j:i] in words:\n                    dp[i] = True\n                    break\n        return dp[-1]`,complexity:'最坏时间 O(n²)，空间 O(n+字典)。',pitfall:'dp 长度为 n+1 且 dp[0]=True；使用集合加速查询。'},
  {id:300,title:'最长递增子序列',category:'动态规划',difficulty:'中等',question:'求严格递增子序列的最长长度。',idea:'维护 tails：tails[i] 是长度 i+1 的递增子序列能取得的最小结尾。对每个数用 bisect_left 替换第一个 ≥x 的结尾，或追加。',code:`from bisect import bisect_left\n\n\nclass Solution:\n    def lengthOfLIS(self, nums):\n        tails = []\n        for x in nums:\n            i = bisect_left(tails, x)\n            if i == len(tails):\n                tails.append(x)\n            else:\n                tails[i] = x\n        return len(tails)`,complexity:'时间 O(n log n)，空间 O(n)。',pitfall:'严格递增用 bisect_left；tails 不是实际 LIS，但长度正确。'},
  {id:152,title:'乘积最大子数组',category:'动态规划',difficulty:'中等',question:'返回连续子数组的最大乘积。',idea:'负数会交换最大和最小的角色，所以同时维护以当前位置结尾的最大乘积和最小乘积。当前值、前最大×当前、前最小×当前三者取极值。',code:`class Solution:\n    def maxProduct(self, nums):\n        current_max = current_min = best = nums[0]\n        for x in nums[1:]:\n            a = current_max * x\n            b = current_min * x\n            current_max = max(x, a, b)\n            current_min = min(x, a, b)\n            best = max(best, current_max)\n        return best`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'a、b 必须用更新前的两个状态计算；0 会自然让状态重新开始。'},
  {id:416,title:'分割等和子集',category:'动态规划',difficulty:'中等',question:'判断数组能否分成元素和相等的两个子集。',idea:'总和为奇数直接失败；目标为 total/2，问题转为 0/1 背包可达性。用一维 dp 并对容量从大到小更新，保证每个数只用一次。',code:`class Solution:\n    def canPartition(self, nums):\n        total = sum(nums)\n        if total % 2:\n            return False\n        target = total // 2\n        dp = [False] * (target + 1)\n        dp[0] = True\n        for x in nums:\n            for s in range(target, x - 1, -1):\n                dp[s] = dp[s] or dp[s - x]\n        return dp[target]`,complexity:'时间 O(n·target)，空间 O(target)。',pitfall:'0/1 背包容量必须倒序；正序会把同一元素重复使用。'},
  {id:32,title:'最长有效括号',category:'动态规划',difficulty:'困难',question:'求最长格式正确的连续括号子串长度。',idea:'栈里保存尚未匹配的左括号下标，初始放 -1 作为有效段左边界。遇到右括号弹栈；栈空就把当前下标作为新边界，否则用 i-stack[-1] 更新答案。',code:`class Solution:\n    def longestValidParentheses(self, s):\n        stack = [-1]\n        best = 0\n        for i, ch in enumerate(s):\n            if ch == "(":\n                stack.append(i)\n            else:\n                stack.pop()\n                if not stack:\n                    stack.append(i)\n                else:\n                    best = max(best, i - stack[-1])\n        return best`,complexity:'时间 O(n)，空间 O(n)。',pitfall:'哨兵 -1 同时处理从 0 开始的有效段；栈空时要压入当前右括号下标。'},
  {id:62,title:'不同路径',category:'多维动态规划',difficulty:'中等',question:'机器人只能向右或向下，求从左上到右下的路径数。',idea:'dp[j] 表示当前行到达第 j 列的路径数。它等于上方旧 dp[j] 加左侧新 dp[j-1]，一维滚动即可。',code:`class Solution:\n    def uniquePaths(self, m, n):\n        dp = [1] * n\n        for _ in range(1, m):\n            for j in range(1, n):\n                dp[j] += dp[j - 1]\n        return dp[-1]`,complexity:'时间 O(mn)，空间 O(n)。',pitfall:'第一行和第一列都只有一种走法，因此初值全为 1。'},
  {id:64,title:'最小路径和',category:'多维动态规划',difficulty:'中等',question:'在非负矩阵中只能向右或向下，求左上到右下的最小路径和。',idea:'一维 dp 记录当前行各列最小路径和。首格、首行、首列单独处理，其他位置取上方和左方较小值再加当前格。',code:`class Solution:\n    def minPathSum(self, grid):\n        m, n = len(grid), len(grid[0])\n        dp = [float("inf")] * n\n        dp[0] = 0\n        for i in range(m):\n            for j in range(n):\n                if j == 0:\n                    dp[j] = dp[j] + grid[i][j]\n                else:\n                    dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]\n        return dp[-1]`,complexity:'时间 O(mn)，空间 O(n)。',pitfall:'dp[0]=0 配合其余无穷可统一首行，但首列只能来自上方。'},
  {id:5,title:'最长回文子串',category:'多维动态规划',difficulty:'中等',question:'返回字符串中最长的回文连续子串。',idea:'中心扩展最适合面试手写：每个位置分别作为奇数中心和偶数中心向两边扩展，记录最长合法区间。',code:`class Solution:\n    def longestPalindrome(self, s):\n        start = end = 0\n\n        def expand(l, r):\n            while l >= 0 and r < len(s) and s[l] == s[r]:\n                l -= 1\n                r += 1\n            return l + 1, r - 1\n\n        for i in range(len(s)):\n            for l, r in (expand(i, i), expand(i, i + 1)):\n                if r - l > end - start:\n                    start, end = l, r\n        return s[start : end + 1]`,complexity:'时间 O(n²)，空间 O(1)。',pitfall:'偶数回文中心是 (i,i+1)；expand 返回越界后的内侧区间。'},
  {id:1143,title:'最长公共子序列',category:'多维动态规划',difficulty:'中等',question:'求两个字符串的最长公共子序列长度。',idea:'dp[i][j] 表示两前缀的 LCS。字符相同取左上+1，否则取上方与左方最大值；用两行滚动降低空间。',code:`class Solution:\n    def longestCommonSubsequence(self, text1, text2):\n        prev = [0] * (len(text2) + 1)\n        for a in text1:\n            cur = [0]\n            for j, b in enumerate(text2, 1):\n                cur.append(prev[j - 1] + 1 if a == b else max(prev[j], cur[j - 1]))\n            prev = cur\n        return prev[-1]`,complexity:'时间 O(mn)，空间 O(n)。',pitfall:'子序列不要求连续；字符不同取 max 而不是加一。'},
  {id:72,title:'编辑距离',category:'多维动态规划',difficulty:'中等',question:'求把 word1 转为 word2 的最少插入、删除、替换次数。',idea:'dp[i][j] 表示两前缀编辑距离。字符相同继承左上；不同则在删除（上）、插入（左）、替换（左上）中取最小再加一。',code:`class Solution:\n    def minDistance(self, word1, word2):\n        prev = list(range(len(word2) + 1))\n        for i, a in enumerate(word1, 1):\n            cur = [i]\n            for j, b in enumerate(word2, 1):\n                if a == b:\n                    cur.append(prev[j - 1])\n                else:\n                    cur.append(1 + min(prev[j], cur[j - 1], prev[j - 1]))\n            prev = cur\n        return prev[-1]`,complexity:'时间 O(mn)，空间 O(n)。',pitfall:'当前行首值为 i；三个方向分别对应删除、插入、替换。'},
  {id:136,title:'只出现一次的数字',category:'技巧',difficulty:'简单',question:'除一个元素只出现一次外，其余元素均出现两次，找出单独元素。',idea:'异或满足 x^x=0、x^0=x 且交换结合，所以把所有数异或后，成对元素抵消，剩下唯一元素。',code:`class Solution:\n    def singleNumber(self, nums):\n        ans = 0\n        for x in nums:\n            ans ^= x\n        return ans`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'这里利用的是恰好出现两次的约束；不要用额外集合。'},
  {id:169,title:'多数元素',category:'技巧',difficulty:'简单',question:'找出数组中出现次数超过一半的元素。',idea:'Boyer-Moore 投票：相同候选票数加一，不同减一；票数归零时更换候选。超过一半的元素最终一定留下。',code:`class Solution:\n    def majorityElement(self, nums):\n        candidate = None\n        count = 0\n        for x in nums:\n            if count == 0:\n                candidate = x\n            count += 1 if x == candidate else -1\n        return candidate`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'算法依赖题目保证多数元素存在；若不保证需再遍历验证。'},
  {id:75,title:'颜色分类',category:'技巧',difficulty:'中等',question:'原地把只含 0、1、2 的数组按颜色排序。',idea:'荷兰国旗三指针：left 左侧全是 0，right 右侧全是 2，i 扫描未知区。遇 0 与 left 换并前进，遇 2 与 right 换但 i 不动，遇 1 直接前进。',code:`class Solution:\n    def sortColors(self, nums):\n        left = i = 0\n        right = len(nums) - 1\n        while i <= right:\n            if nums[i] == 0:\n                nums[left], nums[i] = nums[i], nums[left]\n                left += 1\n                i += 1\n            elif nums[i] == 2:\n                nums[i], nums[right] = nums[right], nums[i]\n                right -= 1\n            else:\n                i += 1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'交换进来的右侧元素还未检查，所以遇到 2 时 i 不能前进。'},
  {id:31,title:'下一个排列',category:'技巧',difficulty:'中等',question:'原地把整数数组变成字典序下一个更大排列；不存在则变最小排列。',idea:'从右找第一个上升拐点 i；再从右找第一个大于 nums[i] 的数交换。此时后缀原本降序，把它反转成升序即可得到最小增量。',code:`class Solution:\n    def nextPermutation(self, nums):\n        i = len(nums) - 2\n        while i >= 0 and nums[i] >= nums[i + 1]:\n            i -= 1\n        if i >= 0:\n            j = len(nums) - 1\n            while nums[j] <= nums[i]:\n                j -= 1\n            nums[i], nums[j] = nums[j], nums[i]\n        left, right = i + 1, len(nums) - 1\n        while left < right:\n            nums[left], nums[right] = nums[right], nums[left]\n            left += 1\n            right -= 1`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'拐点条件是 nums[i]<nums[i+1]；交换后整个后缀反转。'},
  {id:287,title:'寻找重复数',category:'技巧',difficulty:'中等',question:'数组含 n+1 个 [1,n] 整数，仅一个数重复；不能修改数组且只用常数空间。',idea:'把下标看作节点、nums[i] 看作 next，重复值让图形成环。用 Floyd 快慢指针先在环内相遇，再从 0 与相遇点同步走，入口就是重复数。',code:`class Solution:\n    def findDuplicate(self, nums):\n        slow = fast = 0\n        while True:\n            slow = nums[slow]\n            fast = nums[nums[fast]]\n            if slow == fast:\n                break\n        finder = 0\n        while finder != slow:\n            finder = nums[finder]\n            slow = nums[slow]\n        return finder`,complexity:'时间 O(n)，空间 O(1)。',pitfall:'起点用下标 0；第二阶段两个指针都走一步。'},
  {id:239,title:'滑动窗口最大值',category:'子串',difficulty:'困难',question:'返回大小为 k 的每个滑动窗口中的最大值。',idea:'维护下标单调递减队列。新元素入队前弹出所有不大于它的尾部元素；队首若离开窗口则弹出。窗口形成后队首就是最大值。',code:`from collections import deque\n\n\nclass Solution:\n    def maxSlidingWindow(self, nums, k):\n        q = deque()\n        ans = []\n        for i, x in enumerate(nums):\n            while q and nums[q[-1]] <= x:\n                q.pop()\n            q.append(i)\n            if q[0] <= i - k:\n                q.popleft()\n            if i >= k - 1:\n                ans.append(nums[q[0]])\n        return ans`,complexity:'时间 O(n)，空间 O(k)。',pitfall:'队列存下标才能判断过期；先维护单调性，再移除窗口外队首。'},
  {id:76,title:'最小覆盖子串',category:'子串',difficulty:'困难',question:'返回 s 中覆盖 t 全部字符（含重复次数）的最短子串。',idea:'用 need 统计需求，missing 表示还缺多少个字符。右端扩张并减少需求；missing 为 0 时不断收缩左端并更新最短窗口，直到再次缺字符。',code:`from collections import Counter\n\n\nclass Solution:\n    def minWindow(self, s, t):\n        need = Counter(t)\n        missing = len(t)\n        left = 0\n        best = (float("inf"), 0, 0)\n        for right, ch in enumerate(s):\n            if need[ch] > 0:\n                missing -= 1\n            need[ch] -= 1\n            while missing == 0:\n                if right - left + 1 < best[0]:\n                    best = (right - left + 1, left, right + 1)\n                out = s[left]\n                need[out] += 1\n                if need[out] > 0:\n                    missing += 1\n                left += 1\n        return "" if best[0] == float("inf") else s[best[1] : best[2]]`,complexity:'时间 O(n+m)，空间 O(字符集)。',pitfall:'need 可为负表示窗口内多余字符；best 的右端使用开区间。'},
  {id:48,title:'旋转图像',category:'矩阵',difficulty:'中等',question:'原地将 n×n 矩阵顺时针旋转 90 度。',idea:'先沿主对角线转置，再反转每一行，组合起来就是顺时针旋转 90 度。',code:`class Solution:\n    def rotate(self, matrix):\n        n = len(matrix)\n        for i in range(n):\n            for j in range(i + 1, n):\n                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]\n        for row in matrix:\n            row.reverse()`,complexity:'时间 O(n²)，空间 O(1)。',pitfall:'转置只遍历对角线上方 j>i，避免交换两次。'},
  {id:240,title:'搜索二维矩阵 II',category:'矩阵',difficulty:'中等',question:'每行和每列均升序，判断 target 是否存在。',idea:'从右上角开始：当前值太大就左移，太小就下移；每一步排除一行或一列。',code:`class Solution:\n    def searchMatrix(self, matrix, target):\n        row, col = 0, len(matrix[0]) - 1\n        while row < len(matrix) and col >= 0:\n            value = matrix[row][col]\n            if value == target:\n                return True\n            if value > target:\n                col -= 1\n            else:\n                row += 1\n        return False`,complexity:'时间 O(m+n)，空间 O(1)。',pitfall:'右上角同时具备向左变小、向下变大的单调性。'},
];

export const llmCards: HotCard[] = [
  {id:-1,title:'Multi-Head Attention',category:'Transformer',difficulty:'困难',question:'不用框架内置 Attention，用 NumPy 手写多头自注意力，支持 causal 与 padding mask。',idea:'先把输入分别线性投影为 Q/K/V，再 reshape、transpose 成 [B,H,T,D]。计算 QKᵀ/√D，加 mask 后沿最后一维做稳定 softmax，乘 V，最后合并 heads 并输出投影。面试时我会边写边报每一步 shape。',code:`import numpy as np\n\n\ndef softmax(x, axis=-1):\n    x = x - np.max(x, axis=axis, keepdims=True)\n    e = np.exp(x)\n    return e / e.sum(axis=axis, keepdims=True)\n\n\ndef mha(x, wq, wk, wv, wo, heads, mask=None, causal=False):\n    B, T, C = x.shape\n    D = C // heads\n\n    def split(y):\n        return y.reshape(B, T, heads, D).transpose(0, 2, 1, 3)\n\n    q, k, v = split(x @ wq), split(x @ wk), split(x @ wv)\n    scores = q @ k.swapaxes(-1, -2) / np.sqrt(D)\n    if causal:\n        future = np.triu(np.ones((T, T), bool), 1)\n        scores = np.where(future[None, None], -np.inf, scores)\n    if mask is not None:\n        scores = np.where(mask[:, None, None, :], scores, -np.inf)\n    out = softmax(scores, -1) @ v\n    out = out.transpose(0, 2, 1, 3).reshape(B, T, C)\n    return out @ wo`,complexity:'时间 O(B·H·T²·D)，attention score 空间 O(B·H·T²)。',pitfall:'softmax 维度是 key 维；mask 广播到 [B,1,1,T]；hidden 必须能被 heads 整除。'},
  {id:-2,title:'Multi-Token Prediction',category:'Transformer',difficulty:'困难',question:'用 PyTorch 实现简化 MTP：共享 hidden state，一次预测未来 N 个 token 并计算对齐损失。',idea:'为每个未来步建立独立预测头。第 k 个头使用 h[:, :T-k-1] 预测 labels[:, k+1:]，只在两者共同有效长度上计算交叉熵，最后平均各头 loss。重点不是 ModuleList，而是标签对齐。',code:`import torch\nfrom torch import nn\nimport torch.nn.functional as F\n\n\nclass MTPHead(nn.Module):\n    def __init__(self, hidden, vocab, n_future):\n        super().__init__()\n        self.heads = nn.ModuleList(\n            [nn.Linear(hidden, vocab, bias=False) for _ in range(n_future)]\n        )\n\n    def forward(self, h, labels):\n        losses, logits = [], []\n        for k, head in enumerate(self.heads, start=1):\n            pred = head(h[:, :-k])\n            target = labels[:, k:]\n            logits.append(pred)\n            losses.append(\n                F.cross_entropy(\n                    pred.reshape(-1, pred.size(-1)),\n                    target.reshape(-1),\n                    ignore_index=-100,\n                )\n            )\n        return torch.stack(losses).mean(), logits`,complexity:'N 个预测头时约 O(N·B·T·H·V)，输出激活随 N 线性增长。',pitfall:'第 k 个头预测未来 k 步，hidden 与 label 必须错位相同长度；padding 用 ignore_index。'},
  {id:-3,title:'Online Preference Distillation',category:'后训练',difficulty:'困难',question:'根据学生与教师对 chosen/rejected 的序列 log-prob，实现简化 OPD 偏好蒸馏损失。',idea:'先分别得到学生和教师的偏好边际 chosen-rejected，再把边际变成二分类偏好概率。教师分布 detach 作为软标签，学生用 binary cross entropy 学习教师相对偏好。',code:`import torch\nimport torch.nn.functional as F\n\n\ndef opd_loss(\n    student_chosen, student_rejected, teacher_chosen, teacher_rejected, beta=1.0\n):\n    student_margin = beta * (student_chosen - student_rejected)\n    with torch.no_grad():\n        teacher_margin = beta * (teacher_chosen - teacher_rejected)\n        teacher_preference = torch.sigmoid(teacher_margin)\n    return F.binary_cross_entropy_with_logits(student_margin, teacher_preference)`,complexity:'获得四组序列 log-prob 后，loss 计算 O(B)。',pitfall:'输入应先按 response 有效 token 聚合；教师分支必须停止梯度。'},
  {id:-4,title:'RoPE',category:'Transformer',difficulty:'困难',question:'手写旋转位置编码，对 Q/K 的偶数与奇数通道成对旋转。',idea:'每对通道共享位置相关角度。先实现 rotate_half=(-odd,even)，再生成 position×inv_freq 的 cos/sin，并广播到 head 维，返回 x·cos+rotate_half(x)·sin。',code:`import torch\n\n\ndef rotate_half(x):\n    even, odd = x[..., 0::2], x[..., 1::2]\n    return torch.stack((-odd, even), dim=-1).flatten(-2)\n\n\ndef apply_rope(q, k, position_ids, base=10000.0):\n    D = q.size(-1)\n    inv = 1.0 / (base ** (torch.arange(0, D, 2, device=q.device).float() / D))\n    angle = position_ids.float()[..., None] * inv\n    cos = angle.cos().repeat_interleave(2, -1)[:, None].to(q.dtype)\n    sin = angle.sin().repeat_interleave(2, -1)[:, None].to(q.dtype)\n    return (q * cos + rotate_half(q) * sin, k * cos + rotate_half(k) * sin)`,complexity:'时间 O(B·H·T·D)，cos/sin 缓存 O(T·D)。',pitfall:'D 必须为偶数；Q/K 同位置共用相同角度；广播形状是 [B,1,T,D]。'},
  {id:-5,title:'RMSNorm',category:'Transformer',difficulty:'中等',question:'用 PyTorch 手写 RMSNorm，并说明与 LayerNorm 的计算差异。',idea:'RMSNorm 不减均值，只按最后一维的均方根缩放，再乘可学习 scale。统计量用 FP32 计算提升低精度稳定性，最后恢复输入 dtype。',code:`import torch\nfrom torch import nn\n\n\nclass RMSNorm(nn.Module):\n    def __init__(self, hidden_size, eps=1e-6):\n        super().__init__()\n        self.weight = nn.Parameter(torch.ones(hidden_size))\n        self.eps = eps\n\n    def forward(self, x):\n        dtype = x.dtype\n        xf = x.float()\n        inv_rms = torch.rsqrt(xf.pow(2).mean(-1, keepdim=True) + self.eps)\n        return (xf * inv_rms * self.weight.float()).to(dtype)`,complexity:'时间 O(ND)，参数与额外 scale 空间 O(D)。',pitfall:'在最后一维求均方；低精度输入先转 FP32；RMSNorm 不做均值中心化。'},
  {id:-6,title:'KV Cache 单步解码',category:'推理',difficulty:'困难',question:'手写单步 decode attention：更新 K/V cache 并计算当前 token 输出。',idea:'decode 时当前步只生成一个新 Q/K/V。把新 K/V 沿序列维追加到历史 cache，当前 Q 对全部历史 K 做注意力再乘 V，返回输出与更新后的 cache。',code:`import math\nimport torch\n\n\ndef decode_attention(q, k_new, v_new, k_cache=None, v_cache=None):\n    if k_cache is None:\n        k_all, v_all = k_new, v_new\n    else:\n        k_all = torch.cat([k_cache, k_new], dim=2)\n        v_all = torch.cat([v_cache, v_new], dim=2)\n    scores = q @ k_all.transpose(-1, -2) / math.sqrt(q.size(-1))\n    probs = torch.softmax(scores.float(), dim=-1).to(q.dtype)\n    return probs @ v_all, k_all.detach(), v_all.detach()`,complexity:'单步时间 O(B·H·T·D)，cache 空间 O(B·H·T·D)。',pitfall:'只缓存 K/V 不缓存 Q；拼接维是序列维 dim=2；RoPE 应在入 cache 前完成。'},
  {id:-7,title:'Top-p 核采样',category:'采样',difficulty:'中等',question:'用 PyTorch 手写 temperature + top-p sampling，返回 token 与 log-prob。',idea:'temperature 缩放后 softmax，按概率降序排序。保留累计概率达到 p 的最小集合，重归一化后采样，再把排序下标映射回原 token id。',code:`import torch\n\n\ndef top_p_sample(logits, p=0.9, temperature=1.0, generator=None):\n    probs = torch.softmax(logits / temperature, dim=-1)\n    sorted_p, sorted_id = torch.sort(probs, descending=True, dim=-1)\n    remove = torch.cumsum(sorted_p, dim=-1) > p\n    remove[..., 1:] = remove[..., :-1].clone()\n    remove[..., 0] = False\n    sorted_p = sorted_p.masked_fill(remove, 0)\n    sorted_p = sorted_p / sorted_p.sum(-1, keepdim=True)\n    rank = torch.multinomial(sorted_p, 1, generator=generator)\n    token = sorted_id.gather(-1, rank)\n    logp = sorted_p.gather(-1, rank).clamp_min(1e-20).log()\n    return token, logp`,complexity:'排序主导 O(V log V)，额外空间 O(V)。',pitfall:'mask 右移一位以保留越过阈值的第一个 token；候选概率必须重归一。'},
  {id:-8,title:'DPO Loss',category:'后训练',difficulty:'困难',question:'手写 DPO loss，并说明四组 sequence log-prob 的来源。',idea:'分别计算 policy/reference 对 chosen/rejected 的序列 log-prob。用 policy 偏好边际减 reference 偏好边际，乘 beta 后最小化负 log-sigmoid；reference 模型冻结。',code:`import torch.nn.functional as F\n\n\ndef dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta=0.1):\n    policy_margin = policy_chosen - policy_rejected\n    reference_margin = ref_chosen - ref_rejected\n    logits = beta * (policy_margin - reference_margin)\n    loss = -F.logsigmoid(logits).mean()\n    chosen_reward = beta * (policy_chosen - ref_chosen).detach()\n    rejected_reward = beta * (policy_rejected - ref_rejected).detach()\n    return loss, chosen_reward, rejected_reward`,complexity:'log-prob 已聚合后，loss 计算 O(B)。',pitfall:'四组输入是 response 有效 token log-prob 之和；reference 不参与梯度。'},
  {id:-9,title:'GRPO Loss',category:'后训练',difficulty:'困难',question:'手写最小 GRPO：组内 reward 标准化、PPO clip、token mask 与可选 KL。',idea:'每个 prompt 采样 G 个 response，reward 在组内标准化得到 advantage。把它广播到 token 维，用 new/old log-prob ratio 构造 clipped surrogate，再用 response mask 聚合。',code:`import torch\n\n\ndef grpo_loss(\n    new_logp, old_logp, rewards, mask, ref_logp=None, clip_eps=0.2, beta=0.0, eps=1e-6\n):\n    mean = rewards.mean(1, keepdim=True)\n    std = rewards.std(1, keepdim=True, unbiased=False)\n    advantage = ((rewards - mean) / (std + eps)).detach().unsqueeze(-1)\n    ratio = torch.exp(new_logp - old_logp)\n    loss = -torch.minimum(\n        ratio * advantage, ratio.clamp(1 - clip_eps, 1 + clip_eps) * advantage\n    )\n    if ref_logp is not None and beta > 0:\n        delta = ref_logp - new_logp\n        loss = loss + beta * (torch.exp(delta) - delta - 1)\n    return (loss * mask).sum() / mask.sum().clamp_min(1)`,complexity:'loss 计算 O(B·G·T)，主要成本来自 G 条 rollout。',pitfall:'reward 全相同时 advantage 接近 0；mask 掉 prompt/padding；old/ref log-prob 均不回传梯度。'},
  {id:-10,title:'稳定 Softmax 与交叉熵',category:'基础算子',difficulty:'中等',question:'不调用 CrossEntropyLoss，手写数值稳定的 softmax 与交叉熵。',idea:'softmax 先减每行最大值避免 exp 溢出。交叉熵无需显式算 softmax，可直接用 logsumexp(logits)-目标类 logit。',code:`import torch\n\n\ndef stable_softmax(logits, dim=-1):\n    shifted = logits - logits.max(dim=dim, keepdim=True).values\n    exp = shifted.exp()\n    return exp / exp.sum(dim=dim, keepdim=True)\n\n\ndef cross_entropy(logits, targets):\n    log_z = torch.logsumexp(logits, dim=-1)\n    target = logits.gather(1, targets[:, None]).squeeze(1)\n    return (log_z - target).mean()`,complexity:'时间 O(B·C)，额外空间取决于是否保留完整 softmax。',pitfall:'归一化沿类别维；不要先 softmax 再 log；真实场景还要处理 ignore_index。'},
];
